import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / "tools"))

from tools.rstf_adversarial_eval import render_markdown, run_eval


def test_eval_loads_both_positive_and_negative_examples():
    report = run_eval()
    assert report["positive_summary"]["count"] == 12
    assert report["negative_summary"]["count"] == 9


def test_positive_examples_are_detected_and_recovered():
    # These examples are hand-authored / independently recalled, not
    # generated by the module's own encode_* helpers, so this is a
    # non-circular check of the detector's actual behavior.
    report = run_eval()
    assert report["positive_summary"]["detection_rate"] >= 0.9
    assert report["positive_summary"]["recovery_rate"] >= 0.9


def test_legitimate_non_english_text_is_never_flagged():
    # Regression guard for the false-positive bug found by this eval:
    # monolingual Cyrillic/Greek prose was previously flagged as a
    # homoglyph attack 100% of the time (4/4). _normalize_homoglyphs now
    # requires a mix of Latin and confusable characters before flagging.
    report = run_eval()
    assert report["negative_by_category"]["legitimate_non_english"]["false_positive_rate"] == 0.0


def test_overall_false_positive_rate_is_zero():
    report = run_eval()
    assert report["negative_summary"]["false_positive_rate"] == 0.0


def test_markdown_report_documents_provenance():
    report = run_eval()
    md = render_markdown(report)
    assert "not generated by the module" in md
    assert "## Findings" in md
